function lessonPct(){return Math.round((state.doneLessons||[]).length/lessons.length*100);}
window.A1CourseProgressPercent=lessonPct;
function save(completed=false){if(completed)A1Streak.completeExercise();localStorage.setItem(stateKey,JSON.stringify(state));A1Profile.saveProgress('deutsch-a1-tr',state,lessonPct());}
let audioEnabled=localStorage.getItem('trDeA1AudioEnabled')!=='false';
let currentRoute='home';
let activeRecorder=null;
const view=document.getElementById('view');
const audioToggle=document.getElementById('audioToggle');
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const shuffle=A1Learning.shuffle;
const rand=a=>a[Math.floor(Math.random()*a.length)];
function speak(text,force=false,rate=.82){if((!audioEnabled&&!force)||!text)return;A1Voice.speak(text,{lang:'de-DE',rate});}
function speakBtn(text){return `<button class="speak-btn" data-speak="${encodeURIComponent(text)}" aria-label="Telaffuzu dinle">🔊</button>`;}
function wireSpeakButtons(){document.querySelectorAll('[data-speak]').forEach(b=>b.onclick=()=>speak(decodeURIComponent(b.dataset.speak),true));}
function updateAudioButton(){audioToggle.textContent=audioEnabled?'🔊 Auto':'🔇 Auto';audioToggle.classList.toggle('audio-off',!audioEnabled);}
function skillPct(k){if(k==='Dinleme')return Math.round(clamp(state.masteredListening.length/D.listening.length*100,0,100));if(k==='Okuma')return Math.round(clamp(state.masteredReading.length/D.reading.length*100,0,100));if(k==='Yazma')return Math.round(clamp(state.writingDone.length/(D.forms.length+D.writing.length)*100,0,100));if(k==='Konuşma')return Math.round(clamp(new Set(state.speakingDone).size/(D.interview.length+D.infoCards.length+D.requests.length)*100,0,100));return 0;}
function skillBar(k){const p=skillPct(k);return `<div class="skill-row"><strong>${k}</strong><div class="progress"><div style="width:${p}%"></div></div><span>${p}%</span></div>`;}
function setRoute(r){currentRoute=r;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.route===r));({home:renderHome,learn:renderLearn,practice:renderPractice,exam:renderExam}[r]||renderHome)();window.scrollTo({top:0,behavior:'smooth'});}
document.querySelectorAll('.nav-item').forEach(b=>b.onclick=()=>setRoute(b.dataset.route));

function renderHome(){const next=lessons.find(l=>!state.doneLessons.includes(l.id))||lessons[lessons.length-1];view.innerHTML=`<section class="card hero" data-streak-anchor><div class="eyebrow">KURS İLERLEMESİ</div><h2 style="margin-top:12px">Almanca A1 🇩🇪</h2><p class="muted">${state.doneLessons.length}/${lessons.length} ders tamamlandı</p><div class="progress"><div style="width:${lessonPct()}%"></div></div><div class="between" style="margin-top:10px"><small>TÜRKÇE → ALMANCA · A1</small><strong>${lessonPct()}%</strong></div>${A1Streak.render('tr')}</section><section class="card"><div class="between"><div><div class="eyebrow">DEVAM ET</div><h3>${esc(next.title)}</h3></div><span class="pill gray">Ders ${next.id}</span></div><p class="muted">${esc(next.topic)} · ${next.skills.join(' · ')}</p><button class="primary-btn" id="continueLesson">Devam et</button></section><section class="card"><div class="between"><h3>Sınava hazırlık</h3><span class="pill gray">En iyi hızlı test: ${state.bestMock}%</span></div>${['Dinleme','Okuma','Yazma','Konuşma'].map(skillBar).join('')}</section>`;document.getElementById('continueLesson').onclick=()=>renderLesson(next.id);}
function renderLearn(){view.innerHTML=`<section class="card hero"><h2>Almanca A1 kursu</h2><p class="muted">Bu kurs seni Goethe-Zertifikat A1 sınavına hedefli şekilde hazırlar.</p></section><div class="list">${lessons.map(l=>`<button class="lesson ${state.doneLessons.includes(l.id)?'done':''}" data-id="${l.id}"><span class="num">${l.id}</span><strong>${esc(l.title)}</strong><p class="lesson-goal-preview">${A1LessonGuide.goal(l.id,esc)}</p><div class="lesson-meta"><span class="pill gray">${esc(l.topic)}</span>${l.skills.map(s=>`<span class="pill">${s}</span>`).join('')}</div></button>`).join('')}</div>`;document.querySelectorAll('.lesson[data-id]').forEach(b=>b.onclick=()=>renderLesson(+b.dataset.id));}
function renderLesson(id){
  const l=lessons.find(x=>x.id===id),c=window.A1_COURSE_CONTENT.find(x=>x.id===id);
  const goalsHtml=A1LessonGuide.goals(id,'tr',esc);
  const grammarHtml=A1LessonGuide.grammar(id,'tr',esc,speakBtn,{referencesHtml:lessonGrammarReferenceHtml(id)});
  const dialogueHtml=A1LessonGuide.parts(id,'tr',esc,speakBtn).dialogue;
  const model=(c.grammar.examples?.[0]?.[0]||l.phrases[0][0])+' '+l.phrases.slice(1,4).map(p=>p[0]).join(' ');
  A1LessonFlow.render({
    lesson:l,content:c,view,state,save,lessonCount:lessons.length,targetLang:'de',uiLang:'tr',
    goalsHtml,grammarHtml,dialogueHtml,pronunciationHtml:A1Pronunciation.render(c,'de','tr'),
    model,recorderHtml:recorderUI,
    repeatHint:'Örnekleri dinle ve yüksek sesle tekrar et.',speak,speakBtn,wireSpeakButtons,playFeedbackAudio:text=>{if(audioEnabled)speak(text,true);},renderLesson,renderLearn
  });
}

function renderPractice(){view.innerHTML=`<section class="card hero"><h2>Alıştırmalar</h2><p class="muted">Goethe A1 becerilerini ayrı ayrı çalış.</p></section><div class="grid"><button class="practice-card" id="pGrammar"><span class="icon">🧩</span><strong>Gramer</strong><small>8 konu · her biri 10 soru</small></button><button class="practice-card" id="pListen"><span class="icon">🎧</span><strong>Dinleme</strong><small>Almanca ses · her tur 10 soru</small></button><button class="practice-card" id="pRead"><span class="icon">📖</span><strong>Okuma</strong><small>İlanlar, mesajlar ve günlük metinler</small></button><button class="practice-card" id="pWrite"><span class="icon">✍️</span><strong>Yazma</strong><small>Form + kısa mesaj</small></button><button class="practice-card" id="pSpeak"><span class="icon">🎤</span><strong>Konuşma</strong><small>3 bölüm + ses kaydı</small></button></div>`;pGrammar.onclick=renderGrammarMenu;pListen.onclick=()=>runListening(false);pRead.onclick=()=>runReading(false);pWrite.onclick=renderWritingMenu;pSpeak.onclick=renderSpeakingMenu;}
const GRAMMAR_GUIDES={"g1":"<p><strong>sein</strong> (olmak) ve <strong>haben</strong> (sahip olmak) Almancanın en temel iki fiilidir ve düzensiz çekilir.</p><ul class=\"grammar-points\"><li>Kişiye göre fiil biçimi değişir.</li><li>Yaş söylerken Almancada <strong>sein</strong> kullanılır: <em>Ich bin 20 Jahre alt.</em></li><li>Sahiplikte <strong>haben</strong> kullanılır.</li></ul><h3>Örnekler</h3><div class=\"phrase-row\"><div><strong>Ich bin müde.</strong><small>Yorgunum.</small></div></div><div class=\"phrase-row\"><div><strong>Du bist 20 Jahre alt.</strong><small>20 yaşındasın.</small></div></div><div class=\"phrase-row\"><div><strong>Wir haben ein Auto.</strong><small>Bir arabamız var.</small></div></div><details class=\"grammar-detail\"><summary>sein – çekim</summary><div class=\"grammar-detail-body\"><div class=\"grammar-table-wrap\"><table class=\"grammar-table\"><thead><tr><th>Kişi</th><th>Biçim</th></tr></thead><tbody><tr><td>ich</td><td>bin</td></tr><tr><td>du</td><td>bist</td></tr><tr><td>er / sie / es</td><td>ist</td></tr><tr><td>wir</td><td>sind</td></tr><tr><td>ihr</td><td>seid</td></tr><tr><td>sie / Sie</td><td>sind</td></tr></tbody></table></div></div></details><details class=\"grammar-detail\"><summary>haben – çekim</summary><div class=\"grammar-detail-body\"><div class=\"grammar-table-wrap\"><table class=\"grammar-table\"><thead><tr><th>Kişi</th><th>Biçim</th></tr></thead><tbody><tr><td>ich</td><td>habe</td></tr><tr><td>du</td><td>hast</td></tr><tr><td>er / sie / es</td><td>hat</td></tr><tr><td>wir</td><td>haben</td></tr><tr><td>ihr</td><td>habt</td></tr><tr><td>sie / Sie</td><td>haben</td></tr></tbody></table></div></div></details>","g2":"<p>Almancada düzenli fiillerde mastar sonundaki <strong>-en</strong> kaldırılır ve kişiye uygun ek getirilir.</p><ul class=\"grammar-points\"><li>Temel ekler: <strong>-e, -st, -t, -en, -t, -en</strong>.</li><li>Bazı sık fiiller kök değiştirir: <em>essen → du isst</em>, <em>sehen → du siehst</em>.</li><li><strong>gehen</strong> düzenli son ekler alır ama kökü kısa olduğu için biçimleri ayrıca tanımak yararlıdır.</li></ul><h3>Örnekler</h3><div class=\"phrase-row\"><div><strong>Ich wohne in Berlin.</strong><small>Berlin’de oturuyorum.</small></div></div><div class=\"phrase-row\"><div><strong>Wir spielen Fußball.</strong><small>Futbol oynuyoruz.</small></div></div><div class=\"phrase-row\"><div><strong>Du isst heute Suppe.</strong><small>Bugün çorba yiyorsun.</small></div></div><details class=\"grammar-detail\"><summary>Düzenli fiil ekleri</summary><div class=\"grammar-detail-body\"><div class=\"grammar-table-wrap\"><table class=\"grammar-table\"><thead><tr><th>Kişi</th><th>Ek</th><th>lernen örneği</th></tr></thead><tbody><tr><td>ich</td><td>-e</td><td>lerne</td></tr><tr><td>du</td><td>-st</td><td>lernst</td></tr><tr><td>er/sie/es</td><td>-t</td><td>lernt</td></tr><tr><td>wir</td><td>-en</td><td>lernen</td></tr><tr><td>ihr</td><td>-t</td><td>lernt</td></tr><tr><td>sie/Sie</td><td>-en</td><td>lernen</td></tr></tbody></table></div></div></details><details class=\"grammar-detail\"><summary>Alıştırmadaki sık fiiller</summary><div class=\"grammar-detail-body\"><p><strong>wohnen:</strong> ich wohne · du wohnst · er wohnt<br><strong>arbeiten:</strong> ich arbeite · du arbeitest · er arbeitet<br><strong>kommen:</strong> wir kommen · sie kommen<br><strong>trinken:</strong> ihr trinkt</p></div></details><details class=\"grammar-detail\"><summary>Kök değiştiren önemli biçimler</summary><div class=\"grammar-detail-body\"><p><strong>essen:</strong> ich esse, <strong>du isst</strong>, er isst, wir essen<br><strong>sehen:</strong> ich sehe, du siehst, er sieht, <strong>wir sehen</strong><br><strong>gehen:</strong> ich gehe, du gehst, er geht, wir gehen</p></div></details>","g3":"<p>W-Fragen, belirli bir bilgi sormak için kullanılan soru cümleleridir. Soru kelimesinden hemen sonra çekimli fiil gelir.</p><h3>Örnekler</h3><div class=\"phrase-row\"><div><strong>Wo wohnen Sie?</strong><small>Nerede oturuyorsunuz?</small></div></div><div class=\"phrase-row\"><div><strong>Wann beginnt der Kurs?</strong><small>Kurs ne zaman başlıyor?</small></div></div><div class=\"phrase-row\"><div><strong>Wie viel kostet das?</strong><small>Bu ne kadar?</small></div></div><details class=\"grammar-detail\"><summary>Soru kelimeleri</summary><div class=\"grammar-detail-body\"><div class=\"grammar-table-wrap\"><table class=\"grammar-table\"><thead><tr><th>Almanca</th><th>Türkçe</th></tr></thead><tbody><tr><td>wer</td><td>kim</td></tr><tr><td>was</td><td>ne</td></tr><tr><td>wo</td><td>nerede</td></tr><tr><td>woher</td><td>nereden</td></tr><tr><td>wohin</td><td>nereye</td></tr><tr><td>wann</td><td>ne zaman</td></tr><tr><td>wie</td><td>nasıl</td></tr><tr><td>wie viel</td><td>ne kadar</td></tr><tr><td>warum</td><td>neden</td></tr></tbody></table></div></div></details><details class=\"grammar-detail\"><summary>Cümle yapısı</summary><div class=\"grammar-detail-body\"><p><strong>W-kelimesi + çekimli fiil + özne …?</strong><br><em>Wo wohnen Sie?</em><br><em>Warum lernen Sie Deutsch?</em></p></div></details>","g4":"<p>Almancada isimlerin gramatik cinsiyeti vardır ve artikel isimle birlikte öğrenilmelidir.</p><ul class=\"grammar-points\"><li><strong>der</strong> = eril, <strong>die</strong> = dişil, <strong>das</strong> = nötr.</li><li>Belirsiz artikel: eril/nötr <strong>ein</strong>, dişil <strong>eine</strong>.</li><li>Çoğulda belirli artikel <strong>die</strong> olur.</li></ul><h3>Örnekler</h3><div class=\"phrase-row\"><div><strong>der Bahnhof</strong><small>tren istasyonu</small></div></div><div class=\"phrase-row\"><div><strong>die Wohnung</strong><small>daire</small></div></div><div class=\"phrase-row\"><div><strong>das Zimmer</strong><small>oda</small></div></div><details class=\"grammar-detail\"><summary>Nominativ artikel tablosu</summary><div class=\"grammar-detail-body\"><div class=\"grammar-table-wrap\"><table class=\"grammar-table\"><thead><tr><th></th><th>eril</th><th>dişil</th><th>nötr</th><th>çoğul</th></tr></thead><tbody><tr><td>belirli</td><td>der</td><td>die</td><td>das</td><td>die</td></tr><tr><td>belirsiz</td><td>ein</td><td>eine</td><td>ein</td><td>—</td></tr></tbody></table></div></div></details><details class=\"grammar-detail\"><summary>İsimleri artikel ile öğren</summary><div class=\"grammar-detail-body\"><p>Artikel her zaman kelimenin sonundan tahmin edilemez. Yeni kelimeyi <strong>der Tisch, die Straße, das Hotel</strong> şeklinde öğrenmek en güvenlisidir.</p></div></details>","g5":"<p>Akkusativ özellikle doğrudan nesnelerde kullanılır. A1 seviyesinde en belirgin değişiklik eril artikeldedir.</p><ul class=\"grammar-points\"><li>Eril: <strong>der → den</strong>, <strong>ein → einen</strong>.</li><li>Dişil ve nötr biçimler temel örneklerde aynı kalır.</li><li><em>kaufen, sehen, brauchen, bestellen, haben, suchen, nehmen, lesen</em> gibi fiillerle sık görülür.</li></ul><h3>Örnekler</h3><div class=\"phrase-row\"><div><strong>Ich kaufe einen Kaffee.</strong><small>Bir kahve alıyorum.</small></div></div><div class=\"phrase-row\"><div><strong>Sie nimmt die Tasche.</strong><small>Çantayı alıyor.</small></div></div><div class=\"phrase-row\"><div><strong>Wir brauchen ein Auto.</strong><small>Bir arabaya ihtiyacımız var.</small></div></div><details class=\"grammar-detail\"><summary>Akkusativ artikel tablosu</summary><div class=\"grammar-detail-body\"><div class=\"grammar-table-wrap\"><table class=\"grammar-table\"><thead><tr><th></th><th>eril</th><th>dişil</th><th>nötr</th></tr></thead><tbody><tr><td>belirli</td><td>den</td><td>die</td><td>das</td></tr><tr><td>belirsiz</td><td>einen</td><td>eine</td><td>ein</td></tr></tbody></table></div></div></details><details class=\"grammar-detail\"><summary>Nominativ ile karşılaştır</summary><div class=\"grammar-detail-body\"><p><strong>Der Mann</strong> ist hier. → Ich sehe <strong>den Mann</strong>.<br><strong>Ein Kaffee</strong> ist hier. → Ich kaufe <strong>einen Kaffee</strong>.</p></div></details>","g6":"<p>Modal fiiller istek, zorunluluk, izin ve beceri gibi anlamlar verir.</p><ul class=\"grammar-points\"><li>Modal fiil çekimlenir; diğer fiil mastar olarak cümlenin sonuna gider.</li><li><strong>können</strong> = yapabilmek, <strong>müssen</strong> = zorunda olmak, <strong>möchten</strong> = istemek, <strong>dürfen</strong> = izinli olmak.</li><li>Resmî hitapta <strong>Sie</strong> için çoğul biçim kullanılır.</li></ul><h3>Örnekler</h3><div class=\"phrase-row\"><div><strong>Ich kann schwimmen.</strong><small>Yüzebilirim.</small></div></div><div class=\"phrase-row\"><div><strong>Ich muss arbeiten.</strong><small>Çalışmak zorundayım.</small></div></div><div class=\"phrase-row\"><div><strong>Ich möchte einen Tee.</strong><small>Bir çay istiyorum.</small></div></div><details class=\"grammar-detail\"><summary>Modal fiil çekimleri</summary><div class=\"grammar-detail-body\"><div class=\"grammar-table-wrap\"><table class=\"grammar-table\"><thead><tr><th>Kişi</th><th>können</th><th>müssen</th><th>möchten</th><th>dürfen</th></tr></thead><tbody><tr><td>ich</td><td>kann</td><td>muss</td><td>möchte</td><td>darf</td></tr><tr><td>du</td><td>kannst</td><td>musst</td><td>möchtest</td><td>darfst</td></tr><tr><td>er/sie</td><td>kann</td><td>muss</td><td>möchte</td><td>darf</td></tr><tr><td>wir</td><td>können</td><td>müssen</td><td>möchten</td><td>dürfen</td></tr><tr><td>ihr</td><td>könnt</td><td>müsst</td><td>möchtet</td><td>dürft</td></tr><tr><td>sie/Sie</td><td>können</td><td>müssen</td><td>möchten</td><td>dürfen</td></tr></tbody></table></div></div></details><details class=\"grammar-detail\"><summary>Cümle kalıbı</summary><div class=\"grammar-detail-body\"><p><strong>Özne + modal fiil + … + mastar.</strong><br><em>Du musst hier warten.</em><br><em>Wir können morgen kommen.</em><br><em>Können Sie mir helfen?</em></p></div></details>","g7":"<p>İyelik sözcükleri bir şeyin kime ait olduğunu gösterir ve artikel gibi çekimlenir.</p><ul class=\"grammar-points\"><li><strong>mein</strong> = benim, <strong>dein</strong> = senin, <strong>sein</strong> = onun (erkek/nötr), <strong>ihr</strong> = onun (kadın) / onların.</li><li>Dişil ve çoğul nominativde genellikle <strong>-e</strong> gelir: <em>meine Mutter, unsere Eltern</em>.</li><li>Eril Akkusativde <strong>-en</strong> gelir: <em>deinen Lehrer, seinen Schlüssel</em>.</li></ul><h3>Örnekler</h3><div class=\"phrase-row\"><div><strong>Das ist meine Mutter.</strong><small>Bu benim annem.</small></div></div><div class=\"phrase-row\"><div><strong>Wo ist dein Pass?</strong><small>Pasaportun nerede?</small></div></div><div class=\"phrase-row\"><div><strong>Er sucht seinen Schlüssel.</strong><small>Kendi anahtarını arıyor.</small></div></div><details class=\"grammar-detail\"><summary>Temel iyelik kökleri</summary><div class=\"grammar-detail-body\"><div class=\"grammar-table-wrap\"><table class=\"grammar-table\"><thead><tr><th>Kişi</th><th>Kök</th></tr></thead><tbody><tr><td>ich</td><td>mein-</td></tr><tr><td>du</td><td>dein-</td></tr><tr><td>er/es</td><td>sein-</td></tr><tr><td>sie (tekil)</td><td>ihr-</td></tr><tr><td>wir</td><td>unser-</td></tr><tr><td>ihr</td><td>euer-</td></tr><tr><td>sie/Sie</td><td>ihr- / Ihr-</td></tr></tbody></table></div></div></details><details class=\"grammar-detail\"><summary>Nominativ: temel sonlar</summary><div class=\"grammar-detail-body\"><div class=\"grammar-table-wrap\"><table class=\"grammar-table\"><thead><tr><th></th><th>eril</th><th>dişil</th><th>nötr</th><th>çoğul</th></tr></thead><tbody><tr><td>mein-</td><td>mein Bruder</td><td>meine Mutter</td><td>mein Auto</td><td>meine Eltern</td></tr><tr><td>dein-</td><td>dein Pass</td><td>deine Tasche</td><td>dein Kind</td><td>deine Freunde</td></tr></tbody></table></div></div></details><details class=\"grammar-detail\"><summary>Eril Akkusativ</summary><div class=\"grammar-detail-body\"><p>Eril doğrudan nesnede <strong>-en</strong>: <em>deinen Lehrer, seinen Schlüssel, meinen Bruder</em>. Dişil biçim genellikle <strong>-e</strong> olarak kalır: <em>ihre Freundin</em>.</p></div></details>","g8":"<p>Almancada fiilin yeri çok önemlidir. Ayrılabilen fiillerde ön ek ana cümlenin sonuna gider.</p><ul class=\"grammar-points\"><li>Düz cümlede çekimli fiil genellikle <strong>2. konumdadır</strong>.</li><li>Evet/hayır sorusunda çekimli fiil <strong>1. konuma</strong> gelir.</li><li>Ayrılabilen fiilde ön ek sona gider: <em>aufstehen → Ich stehe … auf.</em></li></ul><h3>Örnekler</h3><div class=\"phrase-row\"><div><strong>Heute arbeite ich nicht.</strong><small>Bugün çalışmıyorum.</small></div></div><div class=\"phrase-row\"><div><strong>Kommen Sie morgen?</strong><small>Yarın geliyor musunuz?</small></div></div><div class=\"phrase-row\"><div><strong>Ich stehe um sieben Uhr auf.</strong><small>Saat yedide kalkıyorum.</small></div></div><details class=\"grammar-detail\"><summary>Fiil 2. konumda</summary><div class=\"grammar-detail-body\"><p>Cümle zaman ifadesiyle başlasa bile fiil 2. konumdadır: <em>Am Montag <strong>lerne</strong> ich Deutsch.</em> · <em>Heute <strong>haben</strong> wir keine Zeit.</em></p></div></details><details class=\"grammar-detail\"><summary>Ayrılabilen fiiller – alıştırmadaki biçimler</summary><div class=\"grammar-detail-body\"><div class=\"grammar-table-wrap\"><table class=\"grammar-table\"><thead><tr><th>Mastar</th><th>Cümlede</th></tr></thead><tbody><tr><td>aufstehen</td><td>ich stehe … auf</td></tr><tr><td>abfahren</td><td>der Zug fährt … ab</td></tr><tr><td>anrufen</td><td>ich rufe … an</td></tr><tr><td>ankommen</td><td>er kommt … an</td></tr><tr><td>einkaufen</td><td>wir kaufen … ein</td></tr><tr><td>fernsehen</td><td>Anna sieht … fern</td></tr><tr><td>aufmachen</td><td>ich mache … auf</td></tr><tr><td>anfangen</td><td>der Kurs fängt … an</td></tr></tbody></table></div></div></details><details class=\"grammar-detail\"><summary>Soru kalıbı</summary><div class=\"grammar-detail-body\"><p>Evet/hayır sorusu: <strong>çekimli fiil + özne + …?</strong><br><em>Kommt der Zug pünktlich?</em></p></div></details>"};

